// The FSR 3.1 upscaler's shader blob accessor (ADR 0060), in place of the SDK's
// sdk/src/backends/shared/blob_accessors/ffx_fsr3upscaler_shaderblobs.cpp, which includes
// headers generated by the SDK's shader compiler. The modules and their reflection come
// from examples/ffx_shaders.rs instead: the reflection and the permutation table in
// permutations.inc, the SPIR-V from Rust (src/blobs.rs), handed over at context creation.
// Only the permutations the engine creates contexts for are there.

#include <FidelityFX/host/ffx_util.h>
#include "ffx_fsr3upscaler_shaderblobs.h"
#include "fsr3upscaler/ffx_fsr3upscaler_private.h"

#include <atomic>
#include <cstring>

namespace {

struct EngineFsrResources {
    uint32_t count;
    const char** names;
    const uint32_t* bindings;
    const uint32_t* counts;
    const uint32_t* spaces;
};

struct EngineFsrReflection {
    EngineFsrResources cbv;
    EngineFsrResources srvTexture;
    EngineFsrResources uavTexture;
    EngineFsrResources srvBuffer;
    EngineFsrResources uavBuffer;
    EngineFsrResources sampler;
};

struct EngineFsrPermutation {
    uint32_t shader;
    uint32_t fp16;
    uint32_t options;
    uint32_t module;
};

#include "permutations.inc"

// ENGINE_FSR_SHADER_* in examples/ffx_shaders.rs (`SHADERS`), and whether the SDK's
// accessor has 16-bit variants of it.
constexpr int32_t kNoShader = -1;
constexpr bool kHasFp16[] = {false, false, false, true, true, false, true, false, false, true};

int32_t shaderOf(FfxFsr3UpscalerPass pass)
{
    switch (pass)
    {
    case FFX_FSR3UPSCALER_PASS_PREPARE_INPUTS: return 0;
    case FFX_FSR3UPSCALER_PASS_LUMA_PYRAMID: return 1;
    case FFX_FSR3UPSCALER_PASS_SHADING_CHANGE_PYRAMID: return 2;
    case FFX_FSR3UPSCALER_PASS_SHADING_CHANGE: return 3;
    case FFX_FSR3UPSCALER_PASS_PREPARE_REACTIVITY: return 4;
    case FFX_FSR3UPSCALER_PASS_LUMA_INSTABILITY: return 5;
    case FFX_FSR3UPSCALER_PASS_ACCUMULATE:
    case FFX_FSR3UPSCALER_PASS_ACCUMULATE_SHARPEN: return 6;
    case FFX_FSR3UPSCALER_PASS_RCAS: return 7;
    case FFX_FSR3UPSCALER_PASS_DEBUG_VIEW: return 8;
    case FFX_FSR3UPSCALER_PASS_GENERATE_REACTIVE: return 9;
    default: return kNoShader;
    }
}

std::atomic<const uint8_t* const*> g_modules{nullptr};
std::atomic<const uint32_t*> g_moduleSizes{nullptr};

}  // namespace

extern "C" void engine_fsr_set_modules(const uint8_t* const* data, const uint32_t* sizes, uint32_t count)
{
    if (count != ENGINE_FSR_MODULE_COUNT)
        return;
    g_moduleSizes.store(sizes, std::memory_order_relaxed);
    g_modules.store(data, std::memory_order_release);
}

FfxErrorCode fsr3UpscalerGetPermutationBlobByIndex(FfxFsr3UpscalerPass passId, uint32_t permutationOptions, FfxShaderBlob* outBlob)
{
    std::memset(outBlob, 0, sizeof(FfxShaderBlob));
    const uint8_t* const* modules = g_modules.load(std::memory_order_acquire);
    const uint32_t* sizes = g_moduleSizes.load(std::memory_order_relaxed);
    const int32_t shader = shaderOf(passId);
    if (!modules || shader == kNoShader)
        return FFX_ERROR_INVALID_ARGUMENT;
    const uint32_t fp16 = kHasFp16[shader] && FFX_CONTAINS_FLAG(permutationOptions, FSR3UPSCALER_SHADER_PERMUTATION_ALLOW_FP16) ? 1 : 0;
    // The option bits below FORCE_WAVE64: the defines of the permutation.
    const uint32_t options = permutationOptions & (FSR3UPSCALER_SHADER_PERMUTATION_FORCE_WAVE64 - 1);
    for (const EngineFsrPermutation& p : g_engine_fsr_permutations)
    {
        if (p.shader != uint32_t(shader) || p.fp16 != fp16 || p.options != options)
            continue;
        const EngineFsrReflection& r = g_engine_fsr_reflection[p.module];
        const FfxShaderBlob blob = {
            modules[p.module], sizes[p.module],
            r.cbv.count, r.srvTexture.count, r.uavTexture.count, r.srvBuffer.count, r.uavBuffer.count, r.sampler.count, 0,
            r.cbv.names, r.cbv.bindings, r.cbv.counts, r.cbv.spaces,
            r.srvTexture.names, r.srvTexture.bindings, r.srvTexture.counts, r.srvTexture.spaces,
            r.uavTexture.names, r.uavTexture.bindings, r.uavTexture.counts, r.uavTexture.spaces,
            r.srvBuffer.names, r.srvBuffer.bindings, r.srvBuffer.counts, r.srvBuffer.spaces,
            r.uavBuffer.names, r.uavBuffer.bindings, r.uavBuffer.counts, r.uavBuffer.spaces,
            r.sampler.names, r.sampler.bindings, r.sampler.counts, r.sampler.spaces,
            nullptr, nullptr, nullptr, nullptr,
        };
        std::memcpy(outBlob, &blob, sizeof(FfxShaderBlob));
        return FFX_OK;
    }
    // A permutation examples/ffx_shaders.rs did not generate (context flags the engine
    // does not use).
    return FFX_ERROR_INVALID_ARGUMENT;
}

FfxErrorCode fsr3UpscalerIsWave64(uint32_t permutationOptions, bool& isWave64)
{
    // The same module either way on Vulkan: the backend requests the subgroup size.
    isWave64 = FFX_CONTAINS_FLAG(permutationOptions, FSR3UPSCALER_SHADER_PERMUTATION_FORCE_WAVE64);
    return FFX_OK;
}
